questionvariables.text:
/* Design: simplify with the Pythagorean identity. x is a formal symbol only (no question variable named x): learners type x. Source: original. */
/* A list, a set, an equation or an inequality is invalid, so it never reaches the PRT. */
validate_x(ex) := if listp(ex) or setp(ex) or (not atom(ex) and member(op(ex), ["=", ">", "<", ">=", "<=", "#", "and", "or", "not", "nounand", "nounor", "nounnot"])) then "Type one expression in x, for example 3*cos(x)^2, with no equals sign." elseif every(lambda([v], is(v = x)), listofvars(ex)) then "" else "Use only the letter x, for example 3*cos(x)^2.";
E: [["5 - 5\\sin^2 x", 5-5*sin(x)^2, 5*cos(x)^2], ["\\dfrac{1 - \\cos^2 x}{\\sin x}", (1-cos(x)^2)/sin(x), sin(x)],
 ["\\sin^2 x - 1", sin(x)^2-1, -cos(x)^2], ["3\\sin^2 x + 3\\cos^2 x", 3*sin(x)^2+3*cos(x)^2, 3],
 ["\\dfrac{1 - \\sin^2 x}{\\cos x}", (1-sin(x)^2)/cos(x), cos(x)], ["\\cos^2 x - 1", cos(x)^2-1, -sin(x)^2],
 ["2 - 2\\cos^2 x", 2-2*cos(x)^2, 2*sin(x)^2], ["\\cos x\\sin^2 x + \\cos^3 x", cos(x)*sin(x)^2+cos(x)^3, cos(x)],
 ["(1 - \\sin^2 x)\\tan x", (1-sin(x)^2)*tan(x), sin(x)*cos(x)],
 ["(2\\sin x + \\cos x)^2 + (\\sin x - 2\\cos x)^2", (2*sin(x)+cos(x))^2+(sin(x)-2*cos(x))^2, 5]];
steps: ["5(1 - \\sin^2 x) = 5\\cos^2 x", "\\dfrac{\\sin^2 x}{\\sin x} = \\sin x", "-(1 - \\sin^2 x) = -\\cos^2 x", "3(\\sin^2 x + \\cos^2 x) = 3",
 "\\dfrac{\\cos^2 x}{\\cos x} = \\cos x", "-(1 - \\cos^2 x) = -\\sin^2 x", "2(1 - \\cos^2 x) = 2\\sin^2 x",
 "\\cos x(\\sin^2 x + \\cos^2 x) = \\cos x", "\\cos^2 x \\cdot \\dfrac{\\sin x}{\\cos x} = \\sin x\\cos x",
 "5\\sin^2 x + 5\\cos^2 x = 5(\\sin^2 x + \\cos^2 x) = 5"];
ix: 1+rand(10);
exd: E[ix][1]; ex0: E[ix][2]; ta: E[ix][3]; std: steps[ix];
nta: -ta;
taplus: ta+1;
/* sin(2x)/2 is a single-term form of sin x cos x (entry 9) and is accepted as fully simplified. */
ta2: if ix = 9 then sin(2*x)/2 else ta;
ta3: if ix = 9 then (1/2)*sin(2*x) else ta;

feedbackvariables.text:
samp: [0.3, 0.9, 1.7, 2.6, 4.1, 5.3];
eqv: every(lambda([v], is(abs(float(subst(x=v, ans1-ta))) < 1e-9)), samp);
eqn: every(lambda([v], is(abs(float(subst(x=v, ans1-nta))) < 1e-9)), samp);
altok: is(ix = 9) and freeof(cos, tan, cot, sec, csc, ans1) and is(ratsimp(ans1/sin(2*x)) = 1/2);
sasel: if altok then ta else ans1;
v60: float(subst(x=%pi/3, ex0)); own60: float(subst(x=%pi/3, ans1));
dif60: is(abs(own60 - v60) > 0.0005);
